/** Generated by scaffold-crud-pages. Query hooks for Enrollment.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchEnrollmentList,
  fetchEnrollmentById,
  createEnrollment,
  updateEnrollment,
  deleteEnrollment,
  type FetchEnrollmentListParams,
} from '~/services/httpServices/enrollmentService';
import type { CreateEnrollmentRequest, UpdateEnrollmentRequest } from '~/types/enrollment';

const DOMAIN = 'enrollment';

export function useEnrollmentList(params?: FetchEnrollmentListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchEnrollmentList(params),
  });
}

export function useEnrollment(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchEnrollmentById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateEnrollment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateEnrollmentRequest) => createEnrollment(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateEnrollment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateEnrollmentRequest }) =>
      updateEnrollment(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteEnrollment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteEnrollment(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
